head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[td > P > id]<br/>td 의 ID 를 설정합니다.",
    "validation" : [
        "td 를 구별할 수 있는 유일값을 문자열로 설정할 수 있어야 합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// comp 생성 : tableLayout(tbl1) 의 1행 이름 칸 td 에 con_ID 값을 id 로 설정
scwin.comp_init = async function () {
    // 기존 tableLayout 있으면 삭제 (하위 tr/th/td 함께 삭제)
    if (typeof scwin.tbl1 !== 'undefined') {
        scwin.tbl1.remove();
    }

    $c.gcm.createLabel('label="[대상] 1행 이름 칸(홍길동 입력창이 있는 td)\n[절차] ID 입력 -> Target 재생성\n[확인] getID 버튼으로 대상 td 의 ID 와 렌더링된 td 의 id 확인\n[참고] 예약어(예: scwin, $p) 입력 후 Target 재생성 시 버튼 동작과 콘솔 오류 확인"', '', 'label1');

    // 조건 설정
    let cID = con_ID.getValue();

    // comp 생성 (table 은 scwin.tbl1, 검증 대상 td 는 scwin.target1)
    scwin.tbl1 = await $c.gcm.createBasicTableLayout('', '', 'tbl1', '', { td: 'id="' + cID + '"' });
    scwin.target1 = scwin.tbl1._sub.td;
};



// validation 1, 2 판정 출력 : 대상 td 의 getID() 와 렌더링된 td 요소의 id
scwin.btn_getID_onclick = function (e) {
    let objTd = scwin.target1.render;

    wf_body_bottom.getObj("scwin").setReturnValue("getID() : " + scwin.target1.getID() + " / 렌더링 td id : " + (objTd ? objTd.id : objTd));
};
